<?php declare(strict_types=1);$base=config('app.base_path');$r=$record; ?><div class="page-header"><div><h1><?= htmlspecialchars((string)$r['business_name'],ENT_QUOTES,'UTF-8') ?></h1><p>Fresh Food & Grocery business profile.</p></div><div class="page-actions"><a class="btn btn-secondary" href="<?= $base ?>/fresh-food/businesses">Businesses</a><a class="btn btn-primary" href="<?= $base ?>/fresh-food/businesses/<?= (int)$r['id'] ?>/edit">Edit</a></div></div><div class="card"><h2>Profile</h2><div class="form-grid"><div><strong>Address</strong><p><?= htmlspecialchars((string)$r['address'],ENT_QUOTES,'UTF-8') ?><br><?= htmlspecialchars((string)$r['city'].' · '.$r['district'],ENT_QUOTES,'UTF-8') ?><br><?= htmlspecialchars((string)$r['state'].' · '.$r['postal_code'],ENT_QUOTES,'UTF-8') ?></p></div><div><strong>Coordinates</strong><p><?= $r['latitude']!==null?htmlspecialchars((string)$r['latitude'].' , '.(string)$r['longitude'],ENT_QUOTES,'UTF-8'):'Not configured' ?><?php if($r['latitude']!==null): ?><br><a target="_blank" rel="noopener" href="https://www.google.com/maps?q=<?= rawurlencode((string)$r['latitude'].','.(string)$r['longitude']) ?>">Open in Google Maps</a><?php endif; ?></p></div><div><strong>Delivery</strong><p><?= !empty($r['delivery_available'])?'Enabled':'Disabled' ?><br>₹<?= number_format((float)$r['minimum_delivery_fee'],2) ?> up to <?= number_format((float)$r['included_delivery_distance_km'],2) ?> km<br>₹<?= number_format((float)$r['additional_delivery_fee_per_km'],2) ?>/km after</p></div><div><strong>Pre-order</strong><p><?= !empty($r['preorder_enabled'])?'Enabled':'Disabled' ?><br>₹<?= number_format((float)$r['preorder_delivery_fee'],2) ?> · <?= (int)$r['preorder_min_advance_hours'] ?> hours advance</p></div></div></div><div class="card"><h2>Packing & Status</h2><p>Estimated packing: <?= (int)$r['estimated_packing_minutes_min'] ?>–<?= (int)$r['estimated_packing_minutes_max'] ?> minutes. Orders: <?= !empty($r['accepting_orders'])?'Accepting':'Paused' ?>